package mcp

import (
 "context"
 "encoding/json"
 "os"
 "path/filepath"
 "reflect"
 "testing"
)

// This contract is generated by the actual original TypeScript manager with only
// synthetic process/locator boundaries substituted. It is not a hand-written
// reimplementation. GitHub CI runs the generator before this comparison.
func TestOriginalMCPContract(t *testing.T){
 file:=os.Getenv("GO_MCP_CONTRACT")
 if file==""{if os.Getenv("GITHUB_ACTIONS")=="true"{t.Fatal("GO_MCP_CONTRACT is required in GitHub Actions")};t.Skip("original oracle is CI-only")}
 base:=os.Getenv("RUNNER_TEMP")
 if os.Getenv("GITHUB_ACTIONS")!="true"||base==""||filepath.Clean(file)!=filepath.Join(filepath.Clean(base),"novel-go-mcp","contract.json"){t.Fatal("oracle must be exact synthetic GitHub RUNNER_TEMP path")}
 raw,err:=os.ReadFile(file);if err!=nil{t.Fatal(err)}
 var oracle struct{
  FormatVersion int `json:"formatVersion"`
  Provenance string `json:"provenance"`
  OriginalSSE string `json:"originalSSE"`
  ConfigCases []struct{Raw string `json:"raw"`;Result struct{Status string `json:"status"`;Servers []ServerSummary `json:"servers"`;Error string `json:"error"`} `json:"result"`} `json:"configCases"`
  Catalog struct{Tools []map[string]any `json:"tools"`;Resources []map[string]any `json:"resources"`;Statuses []ServerStatus `json:"statuses"`} `json:"catalog"`
  Calls map[string]CallResult `json:"calls"`
  Disconnected struct{Tools []map[string]any `json:"tools"`;Resources []map[string]any `json:"resources"`;Statuses []ServerStatus `json:"statuses"`} `json:"disconnected"`
  Methods []string `json:"methods"`
 }
 if json.Unmarshal(raw,&oracle)!=nil||oracle.FormatVersion!=1||oracle.Provenance!="actual electron/mcp/mcp-manager.ts with synthetic spawn and locator only"{t.Fatal("invalid original oracle")}
 if len(oracle.ConfigCases)<10||len(oracle.Catalog.Tools)==0||len(oracle.Methods)<4{t.Fatal("empty oracle is not meaningful")}
 for _,entry:=range oracle.ConfigCases{
  got,err:=ParseConfig([]byte(entry.Raw));if entry.Result.Status=="error"{if err==nil{t.Fatalf("original rejected config: %s",entry.Raw)};continue}
  if err!=nil||!reflect.DeepEqual(got,entry.Result.Servers){t.Fatalf("config differential: raw=%s got=%+v err=%v original=%+v",entry.Raw,got,err,entry.Result.Servers)}
 }
 // SSE is a native extension, but the original actual stdio-synthetic oracle
 // still provides authoritative public catalog, call rendering and lifecycle.
 f:=newSyntheticSSE(t,[]map[string]any{fixtureTool()},false)
 m:=configured(t,map[string]any{"url":f.server.URL+"/sse"})
 if err:=m.Connect(context.Background(),"fixture");err!=nil{t.Fatal(err)}
 if got:=m.ListTools();!reflect.DeepEqual(got,oracle.Catalog.Tools){t.Fatalf("tool differential: got=%+v original=%+v",got,oracle.Catalog.Tools)}
 if got:=m.ListResources();!reflect.DeepEqual(got,oracle.Catalog.Resources){t.Fatalf("resource differential: got=%+v original=%+v",got,oracle.Catalog.Resources)}
 if got:=m.ServersStatus();!reflect.DeepEqual(got,oracle.Catalog.Statuses){t.Fatalf("status differential: got=%+v original=%+v",got,oracle.Catalog.Statuses)}
 calls:=map[string]CallResult{
  "known":m.CallTool(context.Background(),"fixture","fixture",map[string]any{}),
  "unknown":m.CallTool(context.Background(),"fixture","not-discovered",map[string]any{}),
  "disconnected":m.CallTool(context.Background(),"missing","fixture",map[string]any{}),
 }
 if !reflect.DeepEqual(calls,oracle.Calls){t.Fatalf("call differential: got=%+v original=%+v",calls,oracle.Calls)}
 m.DisconnectAll()
 if !reflect.DeepEqual(m.ListTools(),oracle.Disconnected.Tools)||!reflect.DeepEqual(m.ListResources(),oracle.Disconnected.Resources)||!reflect.DeepEqual(m.ServersStatus(),oracle.Disconnected.Statuses){t.Fatal("disconnect differential")}
}
